CREATE TABLE migration_000016_dialogue_snapshot AS
SELECT o.id,o.option_text,o.counterparty_reaction
FROM chat_options o
JOIN chat_steps st ON st.id=o.step_id
JOIN chats c ON c.id=st.chat_id
WHERE c.content_status='published' AND c.archived_at IS NULL
  AND c.product_context->>'content_version'='issue-103-complete';
ALTER TABLE migration_000016_dialogue_snapshot ADD PRIMARY KEY(id);

UPDATE chat_options o
SET option_text=regexp_replace(o.option_text,'^(Точно: |Сразу скажу: )','')||CASE
    WHEN l.level_number=2 AND o.sort_order=1 THEN ' Это моё окончательное решение.'
    WHEN l.level_number=2 AND o.sort_order=2 THEN ' Пока продолжать сделку не буду.'
    WHEN l.level_number=2 THEN ' Сделаю это прямо сейчас.'
    WHEN o.sort_order=1 THEN ' Так и начну разговор.'
    WHEN o.sort_order=2 THEN ' Сначала ограничусь этим ответом.'
    ELSE ' С этого и начну.'
END
FROM chat_steps st
JOIN chats c ON c.id=st.chat_id
JOIN levels l ON l.id=c.level_id
WHERE o.step_id=st.id
  AND c.content_status='published' AND c.archived_at IS NULL
  AND c.product_context->>'content_version'='issue-103-complete'
  AND o.option_text ~ '^(Точно:|Сразу скажу:)';

CREATE TABLE migration_000016_reactions (
    topic_slug VARCHAR PRIMARY KEY,
    opening_safe TEXT NOT NULL,
    opening_cautious TEXT NOT NULL,
    opening_unsafe TEXT NOT NULL,
    request_safe TEXT NOT NULL,
    request_cautious TEXT NOT NULL,
    request_unsafe TEXT NOT NULL
);

INSERT INTO migration_000016_reactions VALUES
('buyer-phishing-links','Через приложение получится дольше. Сейчас объясню, как открыть готовую форму.','Телефон исправен, но для доставки всё равно понадобится отдельное подтверждение.','Отлично, сейчас отправлю форму — так оплатить быстрее.','Без моей формы заказ якобы не появится. Решайте быстрее.','Пока вы проверяете, другой покупатель уже готов оплатить.','Подтвердите оплату сейчас, пока форма ещё доступна.'),
('buyer-prepayment','Без перевода бронь не поставлю: желающих на приставку много.','Комплект полный, но решение нужно принять сегодня.','Хорошо, сейчас пришлю реквизиты для брони.','Пока вы проверяете, я не могу обещать, что товар останется.','Проверка займёт время, а следующий покупатель уже ждёт реквизиты.','Переводите сейчас — после этого сразу сниму объявление.'),
('buyer-fake-delivery','Обычная доставка сейчас якобы недоступна, поэтому нужна отдельная страховка.','Комплект полный. Курьер сможет приехать после оплаты страховки.','Отлично, сейчас пришлю форму курьерской службы.','В поддержке будут отвечать долго, а курьер уже ждёт.','Название услуги есть в форме, откройте её и посмотрите.','Оплатите сейчас, иначе курьер уедет и заказ отменится.'),
('buyer-off-platform','В чате видео не загружается. Проще перейти в Telegram.','Камера исправна, полный комплект покажу на видео в Telegram.','Хорошо, сейчас пришлю контакт и QR для просмотра.','Без Telegram и QR видео посмотреть не получится.','QR ведёт только на видео, проверять там якобы нечего.','Переходите сейчас: скидка на доставку скоро исчезнет.'),
('buyer-sms-codes','Самостоятельно отменить второй заказ не получится: нужен код из сообщения.','Лишний заказ уже создан, поэтому важно действовать быстро.','Хорошо, сейчас запрошу код для отмены.','Пока вы проверяете, деньги якобы могут списаться повторно.','Назначение кода неважно, он нужен только для отмены.','Продиктуйте код сейчас, иначе отмена не успеет пройти.'),
('buyer-too-good-offer','Штатно оформить не получится: из-за срочного отъезда нужна бронь через форму.','Цена такая только сегодня, долго проверять предложение не получится.','Отлично, внесите бронь — и ноутбук останется за вами.','Если не открыть форму сейчас, курьер якобы заберёт другой заказ.','Проверяйте быстрее: другой покупатель уже готов внести деньги.','Оплатите сейчас, пока низкая цена ещё действует.'),
('seller-fake-payment','Я уже всё оплатила и отправила курьера. Проверьте сообщение о получении денег.','Курьер приедет сегодня, а оплату я уже отправила.','Отлично, тогда курьер сможет сразу забрать телефон.','Но деньги уже списаны; без подтверждения они якобы зависнут.','Форма обычная, данные карты нужны только для зачисления.','Введите реквизиты, затем останется подтвердить получение денег.'),
('seller-fake-delivery','Заказ уже оформлен, но продавцу нужно отдельно подтвердить страховку курьера.','Курьер приедет сегодня, точное время появится после подтверждения.','Отлично, тогда курьер заберёт кофемашину без задержки.','В заказе страховка не отображается, потому что она якобы курьерская.','Поддержка ответит не сразу, а курьер уже назначен.','Оплатите страховку сейчас, после доставки деньги вернутся.'),
('seller-external-links','В разделе продаж заказ появится только после активации по моей странице.','Курьер назначен, а статус обновится после подтверждения оплаты.','Хорошо, сейчас пришлю страницу с подтверждением заказа.','Без страницы деньги якобы не зачислятся на ваш счёт.','На странице нужно только подтвердить карту получателя.','Активируйте оплату сейчас, иначе она якобы зависнет.'),
('seller-confirmation-codes','Самостоятельная проверка займёт время, а профиль могут заблокировать раньше.','Вижу ошибку подтверждения; специалист уже готов помочь.','Хорошо, сейчас специалист запросит код для подтверждения.','Официальная поддержка ответит позже, а заказ отменится через несколько минут.','Код нужен якобы только для проверки статуса профиля.','Перешлите код сейчас, чтобы заказ не отменился.'),
('seller-off-platform','В этом чате проблема не решится: специалист отвечает только в WhatsApp.','Видео снова не откроется, лучше сразу перейти в другой мессенджер.','Отлично, сейчас пришлю номер специалиста в WhatsApp.','Без номера специалист якобы не сможет найти ваш заказ.','Это служебный контакт, общение там полностью безопасно.','Переходите сейчас, пока обращение не закрыли.'),
('seller-pressure','Я уже перевёл деньги и отправил курьера; ждать проверки он не сможет.','Курьер будет через несколько минут, перевод уже должен прийти.','Отлично, тогда курьер сразу заберёт камеру.','Пока вы открываете банк, курьер якобы начисляет платное ожидание.','Скриншот подтверждает перевод, дополнительная проверка не нужна.','Отдайте камеру сейчас, иначе с меня спишут комиссию.');

UPDATE chat_options o
SET counterparty_reaction=CASE st.step_number
    WHEN 1 THEN (ARRAY[r.opening_safe,r.opening_cautious,r.opening_unsafe])[o.sort_order]
    ELSE (ARRAY[r.request_safe,r.request_cautious,r.request_unsafe])[o.sort_order]
END
FROM chat_steps st
JOIN chats c ON c.id=st.chat_id
JOIN migration_000016_reactions r ON r.topic_slug=c.product_context->>'topic'
WHERE o.step_id=st.id
  AND c.content_status='published' AND c.archived_at IS NULL
  AND c.product_context->>'content_version'='issue-103-complete'
  AND o.counterparty_reaction IS NOT NULL;

DROP TABLE migration_000016_reactions;
